long memo[91];                           /* 0 means not computed yet */

long fib_memo(int n) {                    /* top-down: recursion plus a cache */
  if (n < 2) return n;
  if (memo[n]) return memo[n];
  return memo[n] = fib_memo(n - 1) + fib_memo(n - 2);
}

long fib_tab(int n) {                     /* bottom-up with O(1) space */
  long a = 0, b = 1;
  for (int i = 0; i < n; i++) { long t = a + b; a = b; b = t; }
  return a;
}

/* 0/1 knapsack: best value with capacity W, each item used at most once */
int knapsack(int n, const int wt[], const int val[], int W) {
  int dp[W + 1];                          /* dp[c] = best value with capacity c */
  for (int c = 0; c <= W; c++) dp[c] = 0;
  for (int i = 0; i < n; i++)
    for (int c = W; c >= wt[i]; c--) {    /* go downward so item i is used once */
      int take = dp[c - wt[i]] + val[i];
      if (take > dp[c]) dp[c] = take;
    }
  return dp[W];
}

#include <limits.h>

/* fewest coins to make amount, or -1 */
int coin_change(const int coins[], int n, int amount) {
  int dp[amount + 1];
  dp[0] = 0;
  for (int a = 1; a <= amount; a++) {
    dp[a] = INT_MAX;
    for (int i = 0; i < n; i++)
      if (coins[i] <= a && dp[a - coins[i]] != INT_MAX && dp[a - coins[i]] + 1 < dp[a])
        dp[a] = dp[a - coins[i]] + 1;
  }
  return dp[amount] == INT_MAX ? -1 : dp[amount];
}

#include <string.h>

int lcs(const char *x, const char *y) {
  int m = strlen(x), n = strlen(y);
  int dp[m + 1][n + 1];
  for (int i = 0; i <= m; i++)
    for (int j = 0; j <= n; j++) {
      if (i == 0 || j == 0) dp[i][j] = 0;
      else if (x[i - 1] == y[j - 1]) dp[i][j] = dp[i - 1][j - 1] + 1;
      else dp[i][j] = dp[i - 1][j] > dp[i][j - 1] ? dp[i - 1][j] : dp[i][j - 1];
    }
  return dp[m][n];
}

#include <string.h>

static int min3(int a, int b, int c) { int m = a < b ? a : b; return m < c ? m : c; }

int edit_distance(const char *s, const char *t) {
  int m = strlen(s), n = strlen(t);
  int dp[m + 1][n + 1];
  for (int i = 0; i <= m; i++) dp[i][0] = i;           /* delete everything */
  for (int j = 0; j <= n; j++) dp[0][j] = j;           /* insert everything */
  for (int i = 1; i <= m; i++)
    for (int j = 1; j <= n; j++)
      dp[i][j] = s[i - 1] == t[j - 1] ? dp[i - 1][j - 1]
               : 1 + min3(dp[i - 1][j - 1],            /* replace */
                          dp[i - 1][j],                /* delete */
                          dp[i][j - 1]);               /* insert */
  return dp[m][n];
}

/* length of the longest strictly increasing subsequence, O(n log n) */
int lis(const int a[], int n) {
  int tails[n], len = 0;      /* tails[k]: least tail of a run of length k+1 */
  for (int i = 0; i < n; i++) {
    int lo = 0, hi = len;
    while (lo < hi) {                          /* first tail >= a[i] */
      int mid = (lo + hi) / 2;
      if (tails[mid] < a[i]) lo = mid + 1; else hi = mid;
    }
    tails[lo] = a[i];
    if (lo == len) len++;
  }
  return len;
}

long fib_brute(int n) {                 /* exponential, bounded by O(2^n) */
  if (n <= 1) return n;
  return fib_brute(n - 1) + fib_brute(n - 2);
}

long fib_memo(int n, long memo[]) {       /* memo[] initialized to -1 */
  if (n <= 1) return n;
  if (memo[n] != -1) return memo[n];
  return memo[n] = fib_memo(n - 1, memo) + fib_memo(n - 2, memo);
}

long fib_table(int n) {                   /* tabulation: O(n) time, O(n) space */
  if (n <= 1) return n;
  long dp[n + 1];
  dp[0] = 0; dp[1] = 1;
  for (int i = 2; i <= n; i++) dp[i] = dp[i - 1] + dp[i - 2];
  return dp[n];
}
